-- ROLLBACK for 20260929230000_fll_tp_rhizom_fields_coverage_block4a.sql (deleting a field cascades to entered values — run only if intended).
BEGIN;
DELETE FROM fields f USING worksheet_templates w, standards s WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'FLL-TP-RHIZOM-2023' AND (w.code, f.symbol) IN (('FLLTP-RHZ-05', 'widerlager_eingebaut'), ('FLLTP-RHZ-05', 'widerlager_verzicht_begruendung'), ('FLLTP-RHZ-05', 'kontrollgefaesse_wasserdicht'), ('FLLTP-RHZ-05', 'gefaess_flaeche_m2'), ('FLLTP-RHZ-05', 'gefaess_skalierungsfaktor'), ('FLLTP-RHZ-09', 'standrohr_anzahl'), ('FLLTP-RHZ-09', 'standrohr_laenge_mm'), ('FLLTP-RHZ-17', 'rueckstellprobe_vor_pruefung_datum'), ('FLLTP-RHZ-17', 'rueckstellprobe_nach_pruefung_datum'), ('FLLTP-RHZ-17', 'rueckstellprobe_flaeche_m2'), ('FLLTP-RHZ-17', 'rueckstellprobe_enthaelt_naht_je_fuegetechnik'), ('FLLTP-RHZ-17', 'rueckstellprobe_lager_temp_min_C'), ('FLLTP-RHZ-17', 'rueckstellprobe_lager_temp_max_C'), ('FLLTP-RHZ-17', 'rueckstellprobe_trocken_dunkel'), ('FLLTP-RHZ-17', 'rueckstellprobe_lagerung_bis'), ('FLLTP-RHZ-17', 'lagerung_unvertraeglichkeiten_beachtet'), ('FLLTP-RHZ-20', 'verlaengerung_beantragt'));
DELETE FROM equations e USING worksheet_templates w, standards s WHERE e.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'FLL-TP-RHIZOM-2023' AND (w.code, e.equation_number) IN (('FLLTP-RHZ-05', 'FLLTP-RHZ-05-D1'), ('FLLTP-RHZ-05', 'FLLTP-RHZ-05-D2'), ('FLLTP-RHZ-06', 'FLLTP-RHZ-06-D1'));
UPDATE fields f SET widget = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-06' AND s.code = 'FLL-TP-RHIZOM-2023' AND f.symbol = 'vts_gesamt_dicke_mm' AND f.widget = 'derived';
COMMIT;
